<script lang="ts">
 import{onMount}from"svelte";import{dismissToast,toastStore,notificationStore,clearNotifications,markNotificationsRead}from"../../appshell/lib/toast-core";import{setNotificationCenterOpen,shellStore}from"../../appshell/lib/store";let v=$state(0),tv=$state(0),nv=$state(0);onMount(()=>{const a=shellStore.subscribe(()=>v++),b=toastStore.subscribe(()=>tv++),c=notificationStore.subscribe(()=>nv++);return()=>{a();b();c()}});let open=$derived((v,shellStore.getNotificationCenterOpen()));let toasts=$derived((tv,toastStore.get()));let log=$derived((nv,notificationStore.get()));
</script>
<div class="toasts">{#each toasts as t (t.id)}<div class={`toast ${t.tone}`}><span>{t.message}</span>{#if t.action}<button onclick={t.action.onClick}>{t.action.label}</button>{/if}<button aria-label="Dismiss" onclick={()=>dismissToast(t.id)}>×</button></div>{/each}</div>
{#if open}<aside class="center"><header><strong>Notifications</strong><button onclick={()=>{markNotificationsRead();clearNotifications()}}>Clear</button><button aria-label="Close notifications" onclick={()=>setNotificationCenterOpen(false)}>×</button></header>{#if !log.length}<p>No notifications</p>{/if}{#each log as n (n.id)}<article class:unread={!n.read}><b>{n.tone==="error"?"!":"•"}</b><span>{n.message}</span></article>{/each}</aside>{/if}
<style>.toasts{position:absolute;right:14px;top:44px;z-index:980;display:grid;gap:8px;width:min(380px,90vw)}.toast{display:flex;align-items:center;gap:8px;padding:10px 12px;border-radius:12px;background:#18181be8;color:white;box-shadow:0 12px 36px #0005}.toast span{flex:1}.toast button,.center button{border:0;background:transparent;color:inherit}.success{border-left:3px solid #22c55e}.error{border-left:3px solid #ef4444}.center{position:absolute;z-index:940;right:10px;top:38px;bottom:58px;width:min(360px,92vw);overflow:auto;border:1px solid #ffffff35;border-radius:18px;background:#18181bdc;color:white;backdrop-filter:blur(24px);box-shadow:0 24px 70px #0007;padding:12px}.center header{display:flex;align-items:center;gap:8px;padding:4px 4px 12px}.center header strong{flex:1}.center article{display:flex;gap:10px;padding:12px;border-radius:12px;background:#ffffff0b;margin-bottom:7px}.center article.unread{background:#ffffff16}.center p{text-align:center;color:#aaa;padding:35px}</style>
